{
  "findings": [
    {
      "check_id": "CKV_AWS_24",
      "title": "RDP exposed to the public internet",
      "resource": "aws_security_group_rule.changeme_remote_exec_inline_security_group_rule_incoming_rdp",
      "severity": "HIGH",
      "explanation": "The ingress rule permits TCP port 3389 from 0.0.0.0/0, exposing RDP to internet-wide scanning, brute-force attempts, and exploitation."
    }
  ],
  "patched_code": "variable "rdp_allowed_cidr_blocks" {
  description = "Trusted IPv4 CIDR blocks permitted to access RDP."
  type        = list(string)

  validation {
    condition = length(var.rdp_allowed_cidr_blocks) > 0 && alltrue([
      for cidr in var.rdp_allowed_cidr_blocks :
      try(cidrnetmask(cidr) != "" && tonumber(split("/", cidr)[1]) > 0, false)
    ])
    error_message = "Provide at least one valid IPv4 CIDR block; internet-wide /0 CIDRs are not permitted."
  }
}

resource "aws_security_group_rule" "changeme_remote_exec_inline_security_group_rule_incoming_rdp" {
  security_group_id = aws_security_group.changeme_remote_exec_inline_windows_security_group.id
  type              = "ingress"
  from_port         = 3389
  to_port           = 3389
  protocol          = "tcp"
  cidr_blocks       = var.rdp_allowed_cidr_blocks
}
",
  "fix_summary": "Replaced the internet-wide RDP source with a required allowlist variable. Validation requires valid IPv4 CIDRs and rejects /0 networks."
}
